// Incident templates. Each template describes (a) what is REALLY happening (truth, requirements,
// escalation), (b) what the caller says and can plausibly know, and (c) optional twists.
// The engine rolls variations on top of these: location, caller archetype, patient, severity,
// accuracy of the caller's information, weather and city-event modifiers.
import type { Capability, Category, FactVal, Req } from '../types';

export interface Twist {
  /** topics that make the caller reveal the truth when asked */
  topics: string[]; say: string[]; facts: Record<string, FactVal>;
  /** requirements after the twist (null = unchanged) */
  requires: Req[] | null; label?: string; hint?: string; severity?: number; threat?: number;
  /** also revealed when the first unit arrives on scene */
  scene: string; minCooperation?: number;
}
export interface Escalation { reqs: Req[]; text: string; say?: string[]; sev?: number; casualties?: number; radio?: string }
export interface Template {
  id: string; category: Category; label: string; hint: string; cls: string;
  w: Record<string, number>; minRank: number; intense?: boolean; sev: [number, number];
  patient?: 'child' | 'adult' | 'elder' | 'any' | 'none'; selfOk?: boolean;
  truth: Record<string, FactVal>; reported: string[]; blind?: string[]; unsure?: string[];
  requires: Req[]; escalate?: Escalation[];
  threat: [number, number, number]; work: number; transport?: boolean; lethal?: boolean; closesRoad?: boolean;
  archetypes: Array<[string, number]>;
  open: string[]; selfOpen?: string[]; cause: string[]; say?: Record<string, string[]>;
  twist?: Twist; scene: string; ambience: string; resolved: string; failed: string;
  /** weather / event multipliers */
  weather?: Partial<Record<string, number>>;
  accuracyBias?: Partial<Record<string, number>>;
  outside?: boolean; noMap?: boolean;
  /** chance that the real situation differs; build() mutates a fresh copy */
  build?: (rnd: () => number, t: Template) => Template;
}

const R = (cap: Capability, n = 1): Req => ({ cap, n });

const base = (t: Partial<Template> & Pick<Template, 'id' | 'category' | 'label' | 'hint' | 'cls' | 'w' | 'sev' | 'requires' | 'threat' | 'work' | 'archetypes' | 'open' | 'cause' | 'scene' | 'ambience' | 'resolved' | 'failed'>): Template => ({
  minRank: 1, truth: {}, reported: [], patient: 'none', ...t,
} as Template);

